package com.rulecraft.decisionops.decisionapi.api;import com.rulecraft.decisionops.decisionapi.DecisionApiEvaluationService;import com.rulecraft.decisionops.decisionapi.DecisionApiEvaluationService.*;import com.rulecraft.decisionops.decisionapi.security.DecisionApiPrincipal;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;@RestController @SecurityRequirement(name="decisionApiKey") @RequestMapping("/api/runtime/v1/decisions/{serviceKey}") public class DecisionRuntimeApiController {private final DecisionApiEvaluationService service;public DecisionRuntimeApiController(DecisionApiEvaluationService service){this.service=service;}@PostMapping("/evaluate")SingleResponse evaluate(@PathVariable String serviceKey,@RequestBody SingleCommand body,Authentication auth){return service.single(principal(auth),serviceKey,body);}@PostMapping("/batch")BatchResponse batch(@PathVariable String serviceKey,@RequestBody BatchCommand body,Authentication auth){return service.batch(principal(auth),serviceKey,body);}private DecisionApiPrincipal principal(Authentication auth){return (DecisionApiPrincipal)auth.getPrincipal();}}
